        //call_requests insert
        //$sql999 = "select id, status from call_requests where id <= 1388836 limit 10";
        $sql999 = "select id, status from call_requests where id > 1250000 and id <= 1388836";
        $pArr = $this->v1->query($sql999)->result_array();
        foreach ($pArr as $it)
        {
            echo $it['id'].'-';
            $type = $this->typeChange($it['status']);
            $iArr = [
                'status'=>$type
            ];
            $this->v2->where('callRequestId', $it['id']);
            $this->v2->update('call_request', $iArr);
        }
    }


    /**
     * 신청db 상태 치환 v1 -> v2
     */
    function typeChange($type)
    {
        $ret = '';
        switch ($type)
        {
            case '0':
                $ret = 1;
                break;
            case '1':
                $ret = 1;
                break;
            case '2':
                $ret = 7;
                break;
            case '3':
                $ret = 3;
                break;
            case '4':
                $ret = 5;
                break;
            case '5':
                $ret = 7;
                break;
            case '6':
                $ret = 9;
                break;
            case '7':
                $ret = 2;
                break;
            case '8':
                $ret = 4;
                break;
            case '9':
                $ret = 6;
                break;
            case '10':
                $ret = 8;
                break;
        }

        return $ret;
    }

