        ";
        $sql = "
            select e.* from events e 
            -- left join event_infos ei on e.id=ei.`event_id`
            where e.updated_at > '2019-06-10 00:00:00'
            -- group by e.id
        ";
        $result = $this->v1->query($sql)->result_array();

        $i=1;
        foreach ($result as $v1)
        {
            $sql2 = "select * from ads where id='".$v1['id']."'";
            $v2 = $this->master->query($sql2)->row_array();

            $v1Img1 = 'http://asset.goodoc.kr/images/event/'.$v1['id'].'/t2_'.$v1['image2'];
            $v1Img1 = 'http://asset.goodoc.kr/images/event/'.$v1['id'].'/t2_'.$v1['image2'];

