    /**
     * v2에서 라이브중인데 v1 image2가 없는 리스트.
     *
     */
    function checkV3()
    {
        $this->master = $this->load->database('goodocV2', true); //v2 운영
        $this->v1 = $this->load->database('goodoc', true); //v1 운영

        //10일부터 v1과 v2 달라진 데이터 비교
        //정방향 다른거는 따로 표시. 다른 이벤트번호와 항목을 표시한다.
        $sql = "
            select ah.*, ads.isLive from ads_history ah
             join ads on ah.adsId=ads.id
             where ah.regDate > '2019-06-10 00:00:00' and ah.t2ImageName != '';
        ";

        $result = $this->master->query($sql)->result_array();

        $i=1;
        $arr = [];
        foreach ($result as $v2)
        {
            $sql2 = "select * from events where id='".$v2['adsId']."'";
            $v1 = $this->v1->query($sql2)->row_array();

            //if($v1Img1 != $v2['vT2ImageName'])
            if($v1['image2'] == '' and $v2['isLive'] =='Y')
            //    if(strpos($v2['t2ImageName'], $v1['image2']) === false)
            {

                echo $i.','.$v2['adsId'].','.$v1['image2'] .','. $v2['t2ImageName'].','.$v2['isLive'].'<br>';
                $arr[] = $v2['adsId'];
                $i++;

            }
        }

        echo implode(',', $arr);
    }


