                    $return[$j]['s11'] = $s11;
                    $return[$j]['s12'] = $s12;
                    $return[$j]['s13'] = $s13;

                }
                $j++;
            }

        }

        //dd( $return);

        $csvFileName = 'uploads/revenue-v2-'.time().'.csv';

        //Open file pointer.
        $fp = fopen($csvFileName, 'w');

        //Loop through the associative array.
        foreach($return as $row){
            //Write the row to the CSV file.
            fputcsv($fp, $row);
        }

        //Finally, close the file pointer.
        fclose($fp);

        echo $csvFileName.' done..';
