        $this->load->model('common_m');
        $this->load->model('ads_m');
        $this->load->model('replicator_m');

        $sql = "select * from ads where isLive = 'Y'";
        //$sql = "select * from ads where hospitalId = 179337 and isLive = 'Y'";
        $result = $this->master->query($sql)->result_array(); //dd($Arr3);

        foreach ($result as $item)
        {
            $sql2 = "select * from ads_history where adsId = '".$item['id']."' order by id desc limit 1";
            $result2 = $this->master->query($sql2)->row_array(); //dd($Arr3);

            $this->master->where('id', $item['id'])->update('ads', ['dImageJson'=>$result2['dImageJson']]);
        }
    }

